/* SPDX-License-Identifier: Apache-2.0
 * Unit test for the argument checks (OB_CHECK_*) at the top of sdk_glue.c, run on the host
 * under qemu-ppc64 (see run.sh). sdk_glue.c is included so the test can set its bring-up
 * statics; every SDK function it calls is a stub (stubs.c, generated by run.sh) that logs its
 * name and returns 0. A refused call must return the expected code and log nothing; an
 * accepted call must log the expected first SDK function. */
#include "sdk_glue.c"

#include <stdlib.h>

/* SDK data the glue (and the SOC macros) reference. */
soc_control_t* soc_control[SOC_MAX_NUM_DEVICES];
int soc_ndev;
bcm_control_t* bcm_control[BCM_CONTROL_MAX];
_bcm_l3_module_data_t* l3_module_data[BCM_MAX_NUM_UNITS];
cm_device_t soc_cm_device[SOC_MAX_NUM_DEVICES];

/* soc_attached is part of the check (OB_UNIT_ATTACHED), not an SDK action: not logged. */
static int g_attached[SOC_MAX_NUM_DEVICES];
int soc_attached(int unit)
{
    return unit >= 0 && unit < SOC_MAX_NUM_DEVICES && soc_control[unit] != NULL && g_attached[unit];
}

/* ---------------------------------------------------------------- call log (stubs.c) */
#define LOG_MAX 32
static const char* g_log[LOG_MAX];
static int g_nlog;
void ob_stub_called(const char* name)
{
    if (g_nlog < LOG_MAX) g_log[g_nlog] = name;
    g_nlog++;
}
static void log_reset(void) { g_nlog = 0; }

/* ---------------------------------------------------------------- checks */
static int g_checks, g_failed;

static const char* rvname(int rv)
{
    switch (rv) {
    case OB_E_NONE: return "NONE";
    case OB_E_PARAM: return "PARAM";
    case OB_E_PORT: return "PORT";
    case OB_E_BUSY: return "BUSY";
    case OB_E_INIT: return "INIT";
    case OB_E_UNIT: return "UNIT";
    case OB_E_UNAVAIL: return "UNAVAIL";
    default: return "?";
    }
}

/* first == NULL: no SDK call allowed. */
static void check(const char* phase, const char* what, int rv, int want, const char* first)
{
    int ok = rv == want;
    g_checks++;
    if (first) ok = ok && g_nlog > 0 && strcmp(g_log[0], first) == 0;
    else ok = ok && g_nlog == 0;
    if (ok) {
        printf("ok   [%s] %s -> %s%s%s\n", phase, what, rvname(rv), first ? ", first call " : ", no SDK call",
               first ? first : "");
        return;
    }
    g_failed++;
    printf("FAIL [%s] %s -> %d (%s), want %d (%s); want %s%s; got %d call(s)", phase, what, rv, rvname(rv), want,
           rvname(want), first ? "first call " : "no SDK call", first ? first : "", g_nlog);
    for (int i = 0; i < g_nlog && i < LOG_MAX; i++) printf("%s%s", i ? ", " : ": ", g_log[i]);
    printf("\n");
}

static const char* g_phase = "";
/* Refused: want an error code and no SDK call. */
#define REFUSE(call, want) do { log_reset(); int rv_ = (call); check(g_phase, #call, rv_, (want), NULL); } while (0)
/* Accepted: want rv (0 from the stubs) and this first SDK call (NULL: none). */
#define ACCEPT(call, want, first) do { log_reset(); int rv_ = (call); check(g_phase, #call, rv_, (want), (first)); } while (0)

/* ---------------------------------------------------------------- the 27 checked functions,
 * each with otherwise valid arguments, as f(unit). */
static unsigned g_mdio_val;
enum kind { K_UNIT, K_BCM, K_MDIO, K_OVERTEMP };
static int f_overtemp(int u) { return ob_sdk_th_overtemp_shutdown(u); }
static int f_c45_write(int u) { return ob_sdk_mdio_c45_write(u, 0x1f, 1, 0x1234, 0xbeef); }
static int f_c45_read(int u) { return ob_sdk_mdio_c45_read(u, 0x1f, 1, 0x1234, &g_mdio_val); }
static int f_cpu_port(int u) { return ob_sdk_cpu_port(u); }
static int f_enable(int u) { return ob_sdk_port_enable_set(u, 1, 1); }
static int f_speed(int u) { return ob_sdk_port_speed_set(u, 1, 100000); }
static int f_frame_max(int u) { return ob_sdk_port_frame_max_set(u, 1, 9216); }
static int f_fec(int u) { return ob_sdk_port_fec_set(u, 1, 1); }
static int f_autoneg(int u) { return ob_sdk_port_autoneg_set(u, 1, 0); }
static int f_ifg(int u) { return ob_sdk_port_ifg_set(u, 1, 96); }
static int f_loopback(int u) { return ob_sdk_port_loopback_set(u, 1, 0); }
static int f_pvid(int u) { return ob_sdk_port_pvid_set(u, 1, 1); }
static int f_learn(int u) { return ob_sdk_port_learn_set(u, 1, 0); }
static int f_stat_clear(int u) { return ob_sdk_port_stat_clear(u, 1); }
static int f_vlan_create(int u) { return ob_sdk_vlan_create(u, 10); }
static int f_vlan_destroy(int u) { return ob_sdk_vlan_destroy(u, 10); }
static int f_vlan_port_add(int u) { return ob_sdk_vlan_port_add(u, 10, 1, 1); }
static int f_vlan_port_remove(int u) { return ob_sdk_vlan_port_remove(u, 10, 1); }
static int f_age(int u) { return ob_sdk_l2_age_set(u, 300); }
static int f_netif_destroy(int u) { return ob_sdk_netif_destroy(u, 3, 4); }
static int f_intf_destroy(int u) { return ob_sdk_l3_intf_destroy(u, 1); }
static int f_station_delete(int u) { return ob_sdk_l3_station_delete(u, 1); }
static int f_egress_destroy(int u) { return ob_sdk_l3_egress_destroy(u, 100002); }
static int f_ecmp_destroy(int u) { return ob_sdk_l3_ecmp_destroy(u, 200000); }
static int f_fp_group_destroy(int u) { return ob_sdk_fp_group_destroy(u, 1); }
static int f_fp_entry_destroy(int u) { return ob_sdk_fp_entry_destroy(u, 1, 2); }
static int f_policer_destroy(int u) { return ob_sdk_policer_destroy(u, 1); }

static const struct fn {
    const char* name;
    int (*f)(int);
    enum kind kind;
    const char* first;   /* first SDK call with valid arguments after "init all" */
} fns[] = {
    {"ob_sdk_th_overtemp_shutdown", f_overtemp, K_OVERTEMP, "soc_reg32_get"},
    {"ob_sdk_mdio_c45_write", f_c45_write, K_MDIO, "soc_miimc45_write"},
    {"ob_sdk_mdio_c45_read", f_c45_read, K_MDIO, "soc_miimc45_read"},
    {"ob_sdk_cpu_port", f_cpu_port, K_UNIT, NULL},
    {"ob_sdk_port_enable_set", f_enable, K_BCM, "bcm_port_enable_set"},
    {"ob_sdk_port_speed_set", f_speed, K_BCM, "bcm_port_speed_set"},
    {"ob_sdk_port_frame_max_set", f_frame_max, K_BCM, "bcm_port_frame_max_set"},
    {"ob_sdk_port_fec_set", f_fec, K_BCM, "bcm_port_speed_get"},
    {"ob_sdk_port_autoneg_set", f_autoneg, K_BCM, "bcm_port_autoneg_set"},
    {"ob_sdk_port_ifg_set", f_ifg, K_BCM, "bcm_port_speed_get"},
    {"ob_sdk_port_loopback_set", f_loopback, K_BCM, "bcm_port_loopback_set"},
    {"ob_sdk_port_pvid_set", f_pvid, K_BCM, "bcm_port_untagged_vlan_set"},
    {"ob_sdk_port_learn_set", f_learn, K_BCM, "bcm_port_learn_set"},
    {"ob_sdk_port_stat_clear", f_stat_clear, K_BCM, "bcm_stat_clear"},
    {"ob_sdk_vlan_create", f_vlan_create, K_BCM, "bcm_vlan_create"},
    {"ob_sdk_vlan_destroy", f_vlan_destroy, K_BCM, "bcm_vlan_destroy"},
    {"ob_sdk_vlan_port_add", f_vlan_port_add, K_BCM, "bcm_vlan_port_remove"},
    {"ob_sdk_vlan_port_remove", f_vlan_port_remove, K_BCM, "bcm_vlan_port_remove"},
    {"ob_sdk_l2_age_set", f_age, K_BCM, "bcm_l2_age_timer_set"},
    {"ob_sdk_netif_destroy", f_netif_destroy, K_BCM, "bcm_knet_filter_destroy"},
    {"ob_sdk_l3_intf_destroy", f_intf_destroy, K_BCM, "bcm_l3_intf_t_init"},
    {"ob_sdk_l3_station_delete", f_station_delete, K_BCM, "bcm_l2_station_delete"},
    {"ob_sdk_l3_egress_destroy", f_egress_destroy, K_BCM, "bcm_l3_egress_destroy"},
    {"ob_sdk_l3_ecmp_destroy", f_ecmp_destroy, K_BCM, "bcm_l3_egress_ecmp_t_init"},
    {"ob_sdk_fp_group_destroy", f_fp_group_destroy, K_BCM, "bcm_field_group_destroy"},
    {"ob_sdk_fp_entry_destroy", f_fp_entry_destroy, K_BCM, "bcm_field_entry_remove"},
    {"ob_sdk_policer_destroy", f_policer_destroy, K_BCM, "bcm_policer_destroy"},
};
#define NFNS ((int)(sizeof(fns) / sizeof(fns[0])))
_Static_assert(sizeof(fns) / sizeof(fns[0]) == 27, "27 checked functions");

/* Every function on unit u, expecting the refusal for its kind with no SDK call, or 0: it
 * passes the checks and reaches its first SDK call (cpu_port: none, it returns CMIC_PORT 0). */
static void all_refused(int u, int want_unit, int want_bcm, int want_mdio, int want_overtemp)
{
    char what[96];
    for (int i = 0; i < NFNS; i++) {
        int want = fns[i].kind == K_UNIT ? want_unit : fns[i].kind == K_BCM ? want_bcm
                 : fns[i].kind == K_MDIO ? want_mdio : want_overtemp;
        log_reset();
        int rv = fns[i].f(u);
        snprintf(what, sizeof(what), "%s(unit %d, valid args)", fns[i].name, u);
        check(g_phase, what, rv, want, want == 0 ? fns[i].first : NULL);
    }
}

/* ---------------------------------------------------------------- fake units */
#define NPORTS_VALID 4
static soc_control_t* fake_unit(int u, int tomahawk)
{
    soc_control_t* s = calloc(1, sizeof(*s));
    if (!s) { perror("calloc"); exit(2); }
    soc_control[u] = s;
    SOC_INFO(u).cmic_port = 0;
    SOC_INFO(u).port_type[0] = 1;   /* CPU port; any nonzero type is a valid port */
    for (int p = 1; p <= NPORTS_VALID; p++) SOC_INFO(u).port_type[p] = 1;
    SOC_INFO(u).chip_type = -1;     /* no SOC_INFO_CHIP_TYPE_* (not TH2/TH+) */
    SOC_INFO(u).chip = tomahawk ? SOC_INFO_CHIP_TOMAHAWK : 0;
    return s;
}

static void set_state(int booted, int inited, int mdio, int bcm_unit, int mdio_unit)
{
    sdk_booted = booted;
    sdk_inited = inited;
    mdio_ready = mdio;
    g_bcm_unit = bcm_unit;
    g_mdio_unit = mdio_unit;
}

int main(void)
{
    /* unit 0: attached BCM56960-like (the bring-up unit); 1: absent; 2: present, not attached;
     * 3: attached, not a Tomahawk, never initialised. soc_ndev 4. */
    soc_ndev = 4;
    fake_unit(0, 1);
    g_attached[0] = 1;
    fake_unit(2, 0);
    fake_unit(3, 0);
    g_attached[3] = 1;
    if (!SOC_IS_TOMAHAWK(0) || SOC_IS_TOMAHAWK2(0) || SOC_IS_TOMAHAWK(3)) {
        printf("FAIL harness: fake chip identity wrong\n");
        return 2;
    }
    if (!SOC_PORT_VALID(0, 0) || !SOC_PORT_VALID(0, 4) || SOC_PORT_VALID(0, 5) || SOC_PORT_VALID(0, 300) ||
        SOC_PORT_VALID(0, -1) || CMIC_PORT(0) != 0) {
        printf("FAIL harness: fake port map wrong\n");
        return 2;
    }
    printf("SOC_MAX_NUM_DEVICES %d, SOC_MAX_NUM_PORTS %d, _SHR_PBMP_PORT_MAX %d\n", (int)SOC_MAX_NUM_DEVICES,
           (int)SOC_MAX_NUM_PORTS, (int)_SHR_PBMP_PORT_MAX);

    /* (1) Nothing brought up (the soc layer would even say unit 0 is attached). */
    g_phase = "before boot";
    set_state(0, 0, 0, -1, -1);
    all_refused(0, OB_E_UNIT, OB_E_UNIT, OB_E_INIT, OB_E_UNIT);
    /* Stale ids from an earlier bring-up do not count without the flags. */
    g_phase = "before boot, stale units";
    set_state(0, 0, 0, 0, 0);
    all_refused(0, OB_E_UNIT, OB_E_UNIT, OB_E_INIT, OB_E_UNIT);

    /* (2a) Attached (ob_sdk_attach), nothing initialised. */
    g_phase = "attached only";
    set_state(1, 0, 0, -1, -1);
    for (int i = 0; i < NFNS; i++) {
        if (fns[i].kind == K_BCM) { log_reset(); check(g_phase, fns[i].name, fns[i].f(0), OB_E_INIT, NULL); }
        if (fns[i].kind == K_MDIO) { log_reset(); check(g_phase, fns[i].name, fns[i].f(0), OB_E_INIT, NULL); }
    }
    ACCEPT(ob_sdk_cpu_port(0), 0, NULL);
    ACCEPT(ob_sdk_th_overtemp_shutdown(0), OB_E_NONE, "soc_reg32_get");   /* the reason it exists */
    ACCEPT(ob_sdk_th_overtemp_shutdown(3), OB_E_UNAVAIL, NULL);           /* passes the checks, not a TH */
    REFUSE(ob_sdk_th_overtemp_shutdown(2), OB_E_UNIT);
    REFUSE(ob_sdk_cpu_port(1), OB_E_UNIT);
    /* g_bcm_unit right but "init all" flag not set. */
    g_phase = "attached, g_bcm_unit 0, not inited";
    set_state(1, 0, 0, 0, -1);
    all_refused(0, 0, OB_E_INIT, OB_E_INIT, 0);

    /* (2b) MDIO bring-up only (ob_sdk_init_mdio on unit 0). */
    g_phase = "mdio only";
    set_state(1, 0, 1, -1, 0);
    ACCEPT(f_c45_write(0), OB_E_NONE, "soc_miimc45_write");
    ACCEPT(f_c45_read(0), OB_E_NONE, "soc_miimc45_read");
    REFUSE(f_c45_write(3), OB_E_UNIT);   /* attached, but not the MDIO unit */
    REFUSE(f_c45_read(3), OB_E_UNIT);
    REFUSE(f_c45_write(2), OB_E_UNIT);   /* present, not attached */
    REFUSE(f_c45_read(-1), OB_E_UNIT);
    REFUSE(f_vlan_create(0), OB_E_INIT);
    REFUSE(f_enable(0), OB_E_INIT);
    ACCEPT(ob_sdk_th_overtemp_shutdown(0), OB_E_NONE, "soc_reg32_get");
    g_phase = "booted, mdio flag, no unit";
    set_state(1, 0, 1, -1, -1);
    REFUSE(f_c45_write(0), OB_E_UNIT);
    REFUSE(f_c45_read(0), OB_E_UNIT);

    /* (2c) "init all" on unit 0 (ob_sdk_init sets g_bcm_unit = g_mdio_unit = unit, not mdio_ready). */
    g_phase = "init all: bad unit";
    set_state(1, 1, 0, 0, 0);
    {
        static const int bad[] = {-1, 1, 2, 4, 99, SOC_MAX_NUM_DEVICES, -2147483647 - 1};
        for (unsigned b = 0; b < sizeof(bad) / sizeof(bad[0]); b++)
            all_refused(bad[b], OB_E_UNIT, OB_E_UNIT, OB_E_UNIT, OB_E_UNIT);
    }
    g_phase = "init all: other attached unit";
    all_refused(3, 0, OB_E_INIT, OB_E_UNIT, OB_E_BUSY);   /* cpu_port: 0 = CMIC port, no call */
    g_phase = "init all on unit 3, asked unit 0";
    set_state(1, 1, 0, 3, 3);
    all_refused(0, 0, OB_E_INIT, OB_E_UNIT, OB_E_BUSY);

    g_phase = "init all: bad port";
    set_state(1, 1, 0, 0, 0);
    {
        /* 5: in range, no port type; SOC_MAX_NUM_PORTS - 1: last in range (type 0); then past it. */
        static const int badp[] = {-1, 5, SOC_MAX_NUM_PORTS - 1, SOC_MAX_NUM_PORTS, 192, 300, 2147483647, -2147483647 - 1};
        char what[96];
        for (unsigned b = 0; b < sizeof(badp) / sizeof(badp[0]); b++) {
            int p = badp[b];
#define BADPORT(expr) do { log_reset(); int rv_ = (expr); \
            snprintf(what, sizeof(what), "%s port %d", #expr, p); check(g_phase, what, rv_, OB_E_PORT, NULL); } while (0)
            BADPORT(ob_sdk_port_enable_set(0, p, 1));
            BADPORT(ob_sdk_port_speed_set(0, p, 100000));
            BADPORT(ob_sdk_port_frame_max_set(0, p, 9216));
            BADPORT(ob_sdk_port_fec_set(0, p, 1));
            BADPORT(ob_sdk_port_autoneg_set(0, p, 1));
            BADPORT(ob_sdk_port_ifg_set(0, p, 96));
            BADPORT(ob_sdk_port_loopback_set(0, p, 0));
            BADPORT(ob_sdk_port_pvid_set(0, p, 1));
            BADPORT(ob_sdk_port_learn_set(0, p, 0));
            BADPORT(ob_sdk_port_stat_clear(0, p));
            BADPORT(ob_sdk_vlan_port_add(0, 10, p, 0));
            BADPORT(ob_sdk_vlan_port_remove(0, 10, p));
#undef BADPORT
        }
    }
    /* Port is checked before the other arguments (both bad: PORT). */
    REFUSE(ob_sdk_port_pvid_set(0, 5, 0), OB_E_PORT);

    g_phase = "init all: bad vid";
    {
        static const int badv[] = {0, 4095, -1, 65536 + 10, -2147483647 - 1};
        char what[96];
        for (unsigned b = 0; b < sizeof(badv) / sizeof(badv[0]); b++) {
            int v = badv[b];
#define BADVID(expr) do { log_reset(); int rv_ = (expr); \
            snprintf(what, sizeof(what), "%s vid %d", #expr, v); check(g_phase, what, rv_, OB_E_PARAM, NULL); } while (0)
            BADVID(ob_sdk_port_pvid_set(0, 1, v));
            BADVID(ob_sdk_vlan_create(0, v));
            BADVID(ob_sdk_vlan_destroy(0, v));
            BADVID(ob_sdk_vlan_port_add(0, v, 1, 1));
            BADVID(ob_sdk_vlan_port_remove(0, v, 1));
#undef BADVID
        }
    }

    g_phase = "init all: bad mode / size / id";
    REFUSE(ob_sdk_port_fec_set(0, 1, 3), OB_E_PARAM);
    REFUSE(ob_sdk_port_fec_set(0, 1, -1), OB_E_PARAM);
    REFUSE(ob_sdk_port_loopback_set(0, 1, 3), OB_E_PARAM);
    REFUSE(ob_sdk_port_loopback_set(0, 1, -1), OB_E_PARAM);
    REFUSE(ob_sdk_port_learn_set(0, 1, 4), OB_E_PARAM);
    REFUSE(ob_sdk_port_learn_set(0, 1, -1), OB_E_PARAM);
    REFUSE(ob_sdk_port_speed_set(0, 1, -1), OB_E_PARAM);
    REFUSE(ob_sdk_port_frame_max_set(0, 1, 0), OB_E_PARAM);
    REFUSE(ob_sdk_port_frame_max_set(0, 1, -1), OB_E_PARAM);
    REFUSE(ob_sdk_port_ifg_set(0, 1, -1), OB_E_PARAM);
    REFUSE(ob_sdk_l2_age_set(0, -1), OB_E_PARAM);
    REFUSE(ob_sdk_netif_destroy(0, -2, -1), OB_E_PARAM);
    REFUSE(ob_sdk_netif_destroy(0, -1, -2), OB_E_PARAM);
    REFUSE(ob_sdk_netif_destroy(0, 3, -2), OB_E_PARAM);   /* no partial work: filter refused, netif kept */
    REFUSE(ob_sdk_netif_destroy(0, -2, 4), OB_E_PARAM);
    REFUSE(ob_sdk_l3_intf_destroy(0, -1), OB_E_PARAM);
    REFUSE(ob_sdk_l3_station_delete(0, -1), OB_E_PARAM);
    REFUSE(ob_sdk_l3_egress_destroy(0, -1), OB_E_PARAM);
    REFUSE(ob_sdk_l3_ecmp_destroy(0, -1), OB_E_PARAM);
    REFUSE(ob_sdk_fp_group_destroy(0, -1), OB_E_PARAM);
    REFUSE(ob_sdk_fp_entry_destroy(0, -1, -1), OB_E_PARAM);
    REFUSE(ob_sdk_fp_entry_destroy(0, 1, -2), OB_E_PARAM);
    REFUSE(ob_sdk_policer_destroy(0, -1), OB_E_PARAM);
    REFUSE(ob_sdk_policer_destroy(0, -2147483647 - 1), OB_E_PARAM);

    g_phase = "init all: bad MDIO address";
    REFUSE(ob_sdk_mdio_c45_write(0, 0x800, 1, 0, 0), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_read(0, 0x800, 1, 0, &g_mdio_val), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_write(0, 0xffffffffu, 1, 0, 0), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_write(0, 0x1f, 0, 0, 0), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_read(0, 0x1f, 0, 0, &g_mdio_val), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_write(0, 0x1f, 32, 0, 0), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_read(0, 0x1f, 32, 0, &g_mdio_val), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_write(0, 0x1f, 0xffffffffu, 0, 0), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_write(0, 0x1f, 1, 0x10000, 0), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_read(0, 0x1f, 1, 0x10000, &g_mdio_val), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_write(0, 0x1f, 1, 0, 0x10000), OB_E_PARAM);
    REFUSE(ob_sdk_mdio_c45_write(1, 0x1f, 1, 0, 0), OB_E_UNIT);
    REFUSE(ob_sdk_mdio_c45_read(3, 0x1f, 1, 0, &g_mdio_val), OB_E_UNIT);

    g_phase = "init all: overtemp";
    REFUSE(ob_sdk_th_overtemp_shutdown(0), OB_E_BUSY);
    REFUSE(ob_sdk_th_overtemp_shutdown(1), OB_E_UNIT);

    /* (3) Valid arguments reach the SDK. */
    g_phase = "init all: valid, every function";
    {
        char what[96];
        for (int i = 0; i < NFNS; i++) {
            if (fns[i].kind == K_OVERTEMP) continue;   /* BUSY after init all, above */
            log_reset();
            int rv = fns[i].f(0);
            snprintf(what, sizeof(what), "%s(unit 0, valid args)", fns[i].name);
            check(g_phase, what, rv, 0, fns[i].first);
        }
    }
    g_phase = "init all: valid, range ends";
    ACCEPT(ob_sdk_cpu_port(0), 0, NULL);
    ACCEPT(ob_sdk_port_enable_set(0, 0, 1), 0, "bcm_port_enable_set");   /* CPU port is a valid port */
    ACCEPT(ob_sdk_port_enable_set(0, 4, 0), 0, "bcm_port_enable_set");
    ACCEPT(ob_sdk_port_speed_set(0, 4, 0), 0, "bcm_port_speed_set");
    ACCEPT(ob_sdk_port_frame_max_set(0, 1, 1), 0, "bcm_port_frame_max_set");
    ACCEPT(ob_sdk_port_fec_set(0, 1, 0), 0, "bcm_port_speed_get");
    ACCEPT(ob_sdk_port_fec_set(0, 1, 2), 0, "bcm_port_speed_get");
    ACCEPT(ob_sdk_port_ifg_set(0, 1, 0), 0, "bcm_port_speed_get");
    ACCEPT(ob_sdk_port_loopback_set(0, 1, 2), 0, "bcm_port_loopback_set");
    ACCEPT(ob_sdk_port_learn_set(0, 1, 3), 0, "bcm_port_learn_set");
    ACCEPT(ob_sdk_port_pvid_set(0, 1, 1), 0, "bcm_port_untagged_vlan_set");
    ACCEPT(ob_sdk_port_pvid_set(0, 1, 4094), 0, "bcm_port_untagged_vlan_set");
    ACCEPT(ob_sdk_vlan_create(0, 1), 0, "bcm_vlan_create");
    ACCEPT(ob_sdk_vlan_create(0, 4094), 0, "bcm_vlan_create");
    ACCEPT(ob_sdk_vlan_destroy(0, 4094), 0, "bcm_vlan_destroy");
    ACCEPT(ob_sdk_vlan_port_add(0, 4094, 0, 0), 0, "bcm_vlan_port_remove");
    ACCEPT(ob_sdk_vlan_port_remove(0, 1, 4), 0, "bcm_vlan_port_remove");
    ACCEPT(ob_sdk_port_stat_clear(0, 0), 0, "bcm_stat_clear");
    ACCEPT(ob_sdk_l2_age_set(0, 0), 0, "bcm_l2_age_timer_set");
    ACCEPT(ob_sdk_netif_destroy(0, -1, -1), 0, NULL);                        /* nothing to destroy */
    ACCEPT(ob_sdk_netif_destroy(0, 0, -1), 0, "bcm_knet_netif_destroy");
    ACCEPT(ob_sdk_netif_destroy(0, -1, 0), 0, "bcm_knet_filter_destroy");
    ACCEPT(ob_sdk_l3_intf_destroy(0, 0), 0, "bcm_l3_intf_t_init");
    ACCEPT(ob_sdk_l3_station_delete(0, 0), 0, "bcm_l2_station_delete");
    ACCEPT(ob_sdk_l3_egress_destroy(0, 0), 0, "bcm_l3_egress_destroy");
    ACCEPT(ob_sdk_l3_ecmp_destroy(0, 0), 0, "bcm_l3_egress_ecmp_t_init");
    ACCEPT(ob_sdk_fp_group_destroy(0, 0), 0, "bcm_field_group_destroy");
    ACCEPT(ob_sdk_fp_entry_destroy(0, 0, -1), 0, "bcm_field_entry_remove");
    ACCEPT(ob_sdk_policer_destroy(0, 0), 0, "bcm_policer_destroy");
    ACCEPT(ob_sdk_mdio_c45_write(0, 0, 1, 0, 0), 0, "soc_miimc45_write");
    ACCEPT(ob_sdk_mdio_c45_write(0, 0x7ff, 31, 0xffff, 0xffff), 0, "soc_miimc45_write");
    ACCEPT(ob_sdk_mdio_c45_read(0, 0x7ff, 31, 0xffff, &g_mdio_val), 0, "soc_miimc45_read");
    /* fp_entry_destroy with a stat: the stat is destroyed too (after the entry). */
    log_reset();
    {
        int rv = ob_sdk_fp_entry_destroy(0, 7, 0);
        int ok = rv == 0 && g_nlog == 5 && strcmp(g_log[4], "bcm_field_stat_destroy") == 0;
        g_checks++;
        if (!ok) g_failed++;
        printf("%s [%s] ob_sdk_fp_entry_destroy(0, 7, 0) -> remove, detach, stat detach, destroy, stat destroy (%d calls)\n",
               ok ? "ok  " : "FAIL", g_phase, g_nlog);
    }

    printf("%d checks, %d failed\n", g_checks, g_failed);
    return g_failed ? 1 : 0;
}
